DROP TABLE IF EXISTS `timetable_constraints`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `timetable_constraints` (
  `constraint_id` int NOT NULL AUTO_INCREMENT,
  `department_id` int NOT NULL,
  `scheme_id` int NOT NULL,
  `academic_year` varchar(20) NOT NULL,
  `semester_type` enum('Odd','Even') NOT NULL,
  `semester_id` int NOT NULL,
  `working_days` varchar(100) NOT NULL,
  `periods_per_day` int NOT NULL,
  `college_start_time` time NOT NULL,
  `period_duration` int NOT NULL,
  `lunch_after_period` int NOT NULL,
  `short_break_after_period` int DEFAULT NULL,
  `short_break_duration` int DEFAULT NULL,
  `max_periods_per_day` int NOT NULL,
  `max_periods_per_week` int NOT NULL,
  `lab_duration` int NOT NULL DEFAULT '3',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`constraint_id`),
  KEY `department_id` (`department_id`),
  KEY `scheme_id` (`scheme_id`),
  CONSTRAINT `timetable_constraints_ibfk_1` FOREIGN KEY (`department_id`) REFERENCES `department` (`department_id`),
  CONSTRAINT `timetable_constraints_ibfk_2` FOREIGN KEY (`scheme_id`) REFERENCES `scheme` (`scheme_id`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

